namespace APP\plugins\generic\ojsbrSitemap\classes;

use APP\pages\sitemap\SitemapHandler;
use APP\plugins\generic\ojsbrSitemap\OjsbrSitemapPlugin;
use PKP\facades\Locale;

class SitemapPageHandler extends SitemapHandler
{
    public function __construct(protected OjsbrSitemapPlugin $plugin)
    {
        parent::__construct();
    }

    /**
     * Serve the generated file, with the headers OJS sends with the sitemap.
     */
    public function index($args, $request)
    {
        $context = $request->getContext();
        $file = $context ? $this->plugin->getCache()->fresh($context->getId(), Locale::getLocale()) : null;
        if ($file === null) {
            parent::index($args, $request);
            return;
        }
        header('Content-Type: application/xml');
        header('Cache-Control: private');
        header('Content-Disposition: inline; filename=sitemap.xml');
        header('Content-Length: ' . filesize($file));
        readfile($file);
    }
}
